<script setup lang="ts">
import {useProductivityStore,dateKey} from '~/stores/productivity'; import type {ReportTemplate} from '~/types/domain'; const store=useProductivityStore(); const templateId=ref(store.reportTemplates[0]?.id||''); const achievement=ref(''); const problems=ref(''); const notes=ref(''); const energy=ref(3); const focus=ref(3); const rating=ref(3); const history=computed(()=>Object.values(store.dailyReports).sort((a,b)=>b.date.localeCompare(a.date))); const tpl=computed(()=>store.reportTemplates.find(x=>x.id===templateId.value)||store.reportTemplates[0]);
const generate=()=>{const t=tpl.value;if(!t)return '';const completed=store.tasks.filter(x=>x.scheduledDate===dateKey()&&x.status==='completed');const text=[t.sections.includes('خلاصه روز')?`خلاصه روز: ${achievement.value||'ثبت نشده'}`:'',t.includeCompletedTasks?`کارهای انجام‌شده: ${completed.map(x=>x.title).join('، ')||'موردی ثبت نشده'}`:'',t.includeFocus?`تمرکز: ${store.todayFocusMinutes} دقیقه`:'',t.sections.includes('مشکلات')?`مشکلات: ${problems.value||'موردی ثبت نشده'}`:'',t.sections.includes('قدم بعدی')?`قدم بعدی: ${notes.value||'ادامه برنامه فعلی'}`:'',t.includeStats?`امتیاز روز: ${rating.value}/5 · انرژی ${energy.value}/5 · کیفیت تمرکز ${focus.value}/5`:'' ].filter(Boolean).join('\n');return text.split('\n').slice(0,t.lineCount).join('\n')}
const save=()=>{store.saveReport({achievement:achievement.value,problems:problems.value,notes:notes.value,energy:energy.value,focus:focus.value,rating:rating.value,generatedText:generate()});useToast().add({title:'گزارش ذخیره شد',color:'success'})}
const openTpl=ref(false); const name=ref('قالب من'); const lineCount=ref(8); const sections=ref(['خلاصه روز','کارهای انجام‌شده','مشکلات','قدم بعدی']); const addTemplate=()=>{store.addTemplate({name:name.value,lineCount:lineCount.value,sections:sections.value,includeStats:true,includeCompletedTasks:true,includeFocus:true});openTpl.value=false}
</script>
<template><div class="space-y-5"><div class="flex justify-between gap-3"><div><h1 class="text-2xl font-black">گزارش کار</h1><p class="text-gray-500">قالب را یک بار بساز؛ هر روز گزارش بر اساس همان قالب تولید و ذخیره می‌شود.</p></div><UButton icon="i-lucide-layout-template" variant="soft" @click="openTpl=true">قالب جدید</UButton></div><div class="grid xl:grid-cols-2 gap-4"><UCard><template #header>ورودی گزارش امروز</template><div class="space-y-4"><USelect v-model="templateId" :items="store.reportTemplates.map(x=>({label:x.name,value:x.id}))" value-key="value"/><UTextarea v-model="achievement" placeholder="دستاورد اصلی امروز"/><UTextarea v-model="problems" placeholder="مشکلات و موانع"/><UTextarea v-model="notes" placeholder="یادداشت / قدم بعدی"/><div class="grid grid-cols-3 gap-3"><UInput v-model.number="energy" type="number" min="1" max="5"/><UInput v-model.number="focus" type="number" min="1" max="5"/><UInput v-model.number="rating" type="number" min="1" max="5"/></div><UButton block icon="i-lucide-save" @click="save">ذخیره و تولید گزارش</UButton></div></UCard><UCard><template #header>پیش‌نمایش</template><pre class="whitespace-pre-wrap text-sm leading-8 font-sans">{{generate()||'اطلاعات را وارد کن تا گزارش ساخته شود.'}}</pre></UCard></div><UCard><template #header>گزارش‌های قبلی</template><div v-if="history.length" class="space-y-3"><UAccordion :items="history.map(r=>({label:new Date(r.date+'T12:00').toLocaleDateString('fa-IR',{weekday:'long',day:'numeric',month:'long'}),content:r.generatedText||r.achievement||'گزارش خالی'}))"/></div><p v-else class="text-sm text-gray-500">هنوز گزارشی ذخیره نشده.</p></UCard><UModal v-model:open="openTpl"><template #content><UCard><template #header>ساخت قالب گزارش</template><div class="space-y-4"><UInput v-model="name" placeholder="نام قالب"/><UFormField label="حداکثر خطوط"><UInput v-model.number="lineCount" type="number" min="3" max="30"/></UFormField><UCheckboxGroup v-model="sections" :items="['خلاصه روز','کارهای انجام‌شده','مشکلات','قدم بعدی']"/><div class="flex justify-end gap-2"><UButton variant="ghost" @click="openTpl=false">انصراف</UButton><UButton @click="addTemplate">ذخیره قالب</UButton></div></div></UCard></template></UModal></div></template>
